def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

algorithm:
{
Compute the priority as the negative exponential of the remaining capacity after adding the item, scaled by the bin's current capacity, so that bins with less leftover space and larger current capacity are preferred, while invalid bins receive negative infinity.
}

